from __future__ import annotations

import time
from collections.abc import Callable

from cortex.ai.types import (
    AssistantMessage,
    ImageContent,
    Message,
    Model,
    TextContent,
    ThinkingContent,
    ToolCall,
    ToolResultMessage,
)

NON_VISION_USER_IMAGE_PLACEHOLDER = "(image omitted: model does not support images)"
NON_VISION_TOOL_IMAGE_PLACEHOLDER = "(tool image omitted: model does not support images)"


def _replace_images_with_placeholder(
    content: list[TextContent | ImageContent], placeholder: str
) -> list[TextContent]:
    result: list[TextContent] = []
    previous_was_placeholder = False

    for block in content:
        if block.type == "image":
            if not previous_was_placeholder:
                result.append(TextContent(type="text", text=placeholder))
            previous_was_placeholder = True
            continue

        result.append(block)
        previous_was_placeholder = block.text == placeholder

    return result


def _downgrade_unsupported_images(messages: list[Message], model: Model) -> list[Message]:
    if "image" in model.input:
        return messages

    result: list[Message] = []
    for msg in messages:
        if msg.role == "user" and isinstance(msg.content, list):
            result.append(
                msg.model_copy(
                    update={
                        "content": _replace_images_with_placeholder(
                            msg.content, NON_VISION_USER_IMAGE_PLACEHOLDER
                        )
                    }
                )
            )
        elif msg.role == "toolResult":
            result.append(
                msg.model_copy(
                    update={
                        "content": _replace_images_with_placeholder(
                            msg.content, NON_VISION_TOOL_IMAGE_PLACEHOLDER
                        )
                    }
                )
            )
        else:
            result.append(msg)
    return result


def transform_messages(
    messages: list[Message],
    model: Model,
    normalize_tool_call_id: Callable[[str, Model, AssistantMessage], str] | None = None,
) -> list[Message]:
    """Normalize tool call ID for cross-provider compatibility.

    OpenAI Responses API generates IDs that are 450+ chars with special
    characters like ``|``. Anthropic APIs require IDs matching
    ``^[a-zA-Z0-9_-]+$`` (max 64 chars).
    """
    # Build a map of original tool call IDs to normalized IDs
    tool_call_id_map: dict[str, str] = {}
    image_aware_messages = _downgrade_unsupported_images(messages, model)

    # First pass: transform messages (unsupported image downgrade, thinking
    # blocks, tool call ID normalization)
    transformed: list[Message] = []
    for msg in image_aware_messages:
        # User messages pass through unchanged
        if msg.role == "user":
            transformed.append(msg)
            continue

        # Handle toolResult messages - normalize toolCallId if we have a mapping
        if msg.role == "toolResult":
            normalized_id = tool_call_id_map.get(msg.tool_call_id)
            if normalized_id and normalized_id != msg.tool_call_id:
                transformed.append(msg.model_copy(update={"tool_call_id": normalized_id}))
            else:
                transformed.append(msg)
            continue

        # Assistant messages need transformation check
        if msg.role == "assistant":
            assistant_msg = msg
            is_same_model = (
                assistant_msg.provider == model.provider
                and assistant_msg.api == model.api
                and assistant_msg.model == model.id
            )

            transformed_content: list[TextContent | ThinkingContent | ToolCall] = []
            for block in assistant_msg.content:
                if block.type == "thinking":
                    # Redacted thinking is opaque encrypted content, only valid for
                    # the same model. Drop it for cross-model to avoid API errors.
                    if block.redacted:
                        if is_same_model:
                            transformed_content.append(block)
                        continue
                    # For same model: keep thinking blocks with signatures (needed
                    # for replay) even if the thinking text is empty (OpenAI
                    # encrypted reasoning)
                    if is_same_model and block.thinking_signature:
                        transformed_content.append(block)
                        continue
                    # Skip empty thinking blocks, convert others to plain text
                    if not block.thinking or block.thinking.strip() == "":
                        continue
                    if is_same_model:
                        transformed_content.append(block)
                        continue
                    transformed_content.append(TextContent(type="text", text=block.thinking))
                    continue

                if block.type == "text":
                    if is_same_model:
                        transformed_content.append(block)
                        continue
                    transformed_content.append(TextContent(type="text", text=block.text))
                    continue

                if block.type == "toolCall":
                    tool_call = block
                    normalized_tool_call = tool_call

                    if not is_same_model and tool_call.thought_signature:
                        normalized_tool_call = normalized_tool_call.model_copy(
                            update={"thought_signature": None}
                        )

                    if not is_same_model and normalize_tool_call_id:
                        normalized_id = normalize_tool_call_id(tool_call.id, model, assistant_msg)
                        if normalized_id != tool_call.id:
                            tool_call_id_map[tool_call.id] = normalized_id
                            normalized_tool_call = normalized_tool_call.model_copy(
                                update={"id": normalized_id}
                            )

                    transformed_content.append(normalized_tool_call)
                    continue

                transformed_content.append(block)

            transformed.append(assistant_msg.model_copy(update={"content": transformed_content}))
            continue

        transformed.append(msg)

    # Second pass: insert synthetic empty tool results for orphaned tool calls
    # This preserves thinking signatures and satisfies API requirements
    result: list[Message] = []
    pending_tool_calls: list[ToolCall] = []
    existing_tool_result_ids: set[str] = set()

    def insert_synthetic_tool_results() -> None:
        nonlocal pending_tool_calls, existing_tool_result_ids
        if len(pending_tool_calls) > 0:
            for tc in pending_tool_calls:
                if tc.id not in existing_tool_result_ids:
                    result.append(
                        ToolResultMessage(
                            role="toolResult",
                            tool_call_id=tc.id,
                            tool_name=tc.name,
                            content=[TextContent(type="text", text="No result provided")],
                            is_error=True,
                            timestamp=int(time.time() * 1000),
                        )
                    )
            pending_tool_calls = []
            existing_tool_result_ids = set()

    for msg in transformed:
        if msg.role == "assistant":
            # If we have pending orphaned tool calls from a previous assistant,
            # insert synthetic results now
            insert_synthetic_tool_results()

            # Skip errored/aborted assistant messages entirely.
            # These are incomplete turns that shouldn't be replayed:
            # - May have partial content (reasoning without message, incomplete
            #   tool calls)
            # - Replaying them can cause API errors (e.g., OpenAI "reasoning
            #   without following item")
            # - The model should retry from the last valid state
            assistant_msg = msg
            if assistant_msg.stop_reason in ("error", "aborted"):
                continue

            # Track tool calls from this assistant message
            tool_calls = [b for b in assistant_msg.content if b.type == "toolCall"]
            if len(tool_calls) > 0:
                pending_tool_calls = tool_calls
                existing_tool_result_ids = set()

            result.append(msg)
        elif msg.role == "toolResult":
            existing_tool_result_ids.add(msg.tool_call_id)
            result.append(msg)
        elif msg.role == "user":
            # User message interrupts tool flow - insert synthetic results for
            # orphaned calls
            insert_synthetic_tool_results()
            result.append(msg)
        else:
            result.append(msg)

    # If the conversation ends with unresolved tool calls, synthesize results now.
    insert_synthetic_tool_results()

    return result

from __future__ import annotations

from typing import Literal

from cortex.ai.types import Message


def infer_copilot_initiator(messages: list[Message]) -> Literal["user", "agent"]:
    # Copilot expects X-Initiator to indicate whether the request is
    # user-initiated or agent-initiated (e.g. follow-up after assistant/tool
    # messages).
    last = messages[-1] if messages else None
    return "agent" if last and last.role != "user" else "user"


def has_copilot_vision_input(messages: list[Message]) -> bool:
    # Copilot requires Copilot-Vision-Request header when sending images
    for msg in messages:
        if msg.role == "user" and isinstance(msg.content, list):
            if any(c.type == "image" for c in msg.content):
                return True
        if msg.role == "toolResult":
            if any(c.type == "image" for c in msg.content):
                return True
    return False


def build_copilot_dynamic_headers(
    messages: list[Message],
    has_images: bool,
) -> dict[str, str]:
    headers: dict[str, str] = {
        "X-Initiator": infer_copilot_initiator(messages),
        "Openai-Intent": "conversation-edits",
    }

    if has_images:
        headers["Copilot-Vision-Request"] = "true"

    return headers

"""JSON repair and parsing utilities.

Port of hoocode's `packages/ai/src/utils/json-parse.ts`.
"""

from typing import Any

VALID_JSON_ESCAPES = frozenset(['"', "\\", "/", "b", "f", "n", "r", "t", "u"])


def _is_control_character(char: str) -> bool:
    """Check if a character is a control character (0x00-0x1F)."""
    code_point = ord(char)
    return 0x00 <= code_point <= 0x1F


def _escape_control_character(char: str) -> str:
    """Escape a control character for JSON."""
    if char == "\b":
        return "\\b"
    elif char == "\f":
        return "\\f"
    elif char == "\n":
        return "\\n"
    elif char == "\r":
        return "\\r"
    elif char == "\t":
        return "\\t"
    else:
        return f"\\u{ord(char):04x}"


def repair_json(json_str: str) -> str:
    """Repair malformed JSON string literals.

    Handles:
    - Raw control characters inside strings
    - Doubled backslashes before invalid escape characters

    Args:
        json_str: The potentially malformed JSON string.

    Returns:
        The repaired JSON string.
    """
    repaired = []
    in_string = False
    index = 0
    length = len(json_str)

    while index < length:
        char = json_str[index]

        if not in_string:
            repaired.append(char)
            if char == '"':
                in_string = True
            index += 1
            continue

        if char == '"':
            repaired.append(char)
            in_string = False
            index += 1
            continue

        if char == "\\":
            if index + 1 >= length:
                repaired.append("\\\\")
                index += 1
                continue

            next_char = json_str[index + 1]

            if next_char == "u":
                unicode_digits = json_str[index + 2 : index + 6]
                if len(unicode_digits) == 4 and all(
                    c in "0123456789abcdefABCDEF" for c in unicode_digits
                ):
                    repaired.append(f"\\u{unicode_digits}")
                    index += 6
                    continue

            if next_char in VALID_JSON_ESCAPES:
                repaired.append(f"\\{next_char}")
                index += 2
                continue

            repaired.append("\\\\")
            index += 1
            continue

        repaired.append(_escape_control_character(char) if _is_control_character(char) else char)
        index += 1

    return "".join(repaired)


def parse_json_with_repair(json_str: str) -> Any:
    """Parse JSON with automatic repair on failure.

    Args:
        json_str: The JSON string to parse.

    Returns:
        The parsed object.

    Raises:
        ValueError: If parsing fails even after repair.
    """
    import json

    try:
        return json.loads(json_str)
    except ValueError:
        repaired_json = repair_json(json_str)
        if repaired_json != json_str:
            return json.loads(repaired_json)
        raise


def parse_streaming_json(partial_json: str | None = None) -> dict[str, Any]:
    """Parse potentially incomplete JSON during streaming.

    Always returns a valid object, even if the JSON is incomplete.

    Args:
        partial_json: The partial JSON string from streaming.

    Returns:
        Parsed object or empty dict if parsing fails.
    """
    if not partial_json or partial_json.strip() == "":
        return {}

    try:
        result = parse_json_with_repair(partial_json)
        return result if isinstance(result, dict) else {}
    except (ValueError, Exception):
        return {}

