"""Anthropic Messages API provider.

Mechanical port of hoocode's ``packages/ai/src/providers/anthropic.ts``.
"""

from __future__ import annotations

import asyncio
import inspect
import json
import re
import time
from collections.abc import AsyncIterator
from dataclasses import dataclass, field
from typing import Any, Literal

import httpx

from cortex.ai.env import get_env_api_key
from cortex.ai.models import calculate_cost
from cortex.ai.providers._common import (
    adjust_max_tokens_for_thinking,
    build_base_options,
    build_copilot_dynamic_headers,
    has_copilot_vision_input,
    resolve_cache_retention,
    transform_messages,
)
from cortex.ai.stream import (
    AssistantMessageEventStream,
    create_assistant_message_event_stream,
)
from cortex.ai.types import (
    AnthropicMessagesCompat,
    AssistantMessage,
    CacheRetention,
    Context,
    ImageContent,
    Message,
    Model,
    SimpleStreamOptions,
    StopReason,
    StreamOptions,
    TextContent,
    ThinkingContent,
    Tool,
    ToolCall,
    ToolResultMessage,
    Usage,
)
from cortex.ai.util import (
    headers_to_record,
    parse_json_with_repair,
    parse_streaming_json,
    sanitize_surrogates,
)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

ANTHROPIC_VERSION = "2023-06-01"
CLAUDE_CODE_VERSION = "2.1.75"
FINE_GRAINED_TOOL_STREAMING_BETA = "fine-grained-tool-streaming-2025-05-14"
INTERLEAVED_THINKING_BETA = "interleaved-thinking-2025-05-14"

_ANTHROPIC_MESSAGE_EVENTS: frozenset[str] = frozenset({
    "message_start",
    "message_delta",
    "message_stop",
    "content_block_start",
    "content_block_delta",
    "content_block_stop",
})

_STOP_REASON_MAP: dict[str, StopReason] = {
    "end_turn": "stop",
    "max_tokens": "length",
    "tool_use": "toolUse",
    "refusal": "error",
    "pause_turn": "stop",
    "stop_sequence": "stop",
    "sensitive": "error",
}

ANTHROPIC_THINKING_LEVEL_TO_EFFORT: dict[str, str] = {
    "minimal": "low",
    "low": "low",
    "medium": "medium",
    "high": "high",
}

# Claude Code 2.x tool names (canonical casing)
_CLAUDE_CODE_TOOLS = [
    "Read",
    "Write",
    "Edit",
    "Bash",
    "Grep",
    "Glob",
    "AskUserQuestion",
    "EnterPlanMode",
    "ExitPlanMode",
    "KillShell",
    "NotebookEdit",
    "Skill",
    "Task",
    "TaskOutput",
    "TodoWrite",
    "WebFetch",
    "WebSearch",
]

_CC_TOOL_LOOKUP: dict[str, str] = {t.lower(): t for t in _CLAUDE_CODE_TOOLS}

AnthropicEffort = Literal["low", "medium", "high", "xhigh", "max"]
AnthropicThinkingDisplay = Literal["summarized", "omitted"]


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------


@dataclass
class AnthropicOptions(StreamOptions):
    thinking_enabled: bool | None = None
    thinking_budget_tokens: int | None = None
    effort: AnthropicEffort | None = None
    thinking_display: AnthropicThinkingDisplay | None = None
    interleaved_thinking: bool | None = None
    tool_choice: str | dict[str, Any] | None = None
    client: Any | None = None


# ---------------------------------------------------------------------------
# SSE parsing
# ---------------------------------------------------------------------------


class _SseDecoderState:
    __slots__ = ("event", "data", "raw")

    def __init__(self) -> None:
        self.event: str | None = None
        self.data: list[str] = []
        self.raw: list[str] = []


class _SseEvent:
    __slots__ = ("event", "data", "raw")

    def __init__(self, event: str | None, data: str, raw: list[str]) -> None:
        self.event = event
        self.data = data
        self.raw = raw


def _flush_sse_event(state: _SseDecoderState) -> _SseEvent | None:
    if not state.event and not state.data:
        return None
    event = _SseEvent(event=state.event, data="\n".join(state.data), raw=list(state.raw))
    state.event = None
    state.data = []
    state.raw = []
    return event


def _decode_sse_line(line: str, state: _SseDecoderState) -> _SseEvent | None:
    if line == "":
        return _flush_sse_event(state)
    state.raw.append(line)
    if line.startswith(":"):
        return None
    colon_idx = line.find(":")
    if colon_idx == -1:
        field_name = line
        value = ""
    else:
        field_name = line[:colon_idx]
        value = line[colon_idx + 1 :]
        if value.startswith(" "):
            value = value[1:]
    if field_name == "event":
        state.event = value
    elif field_name == "data":
        state.data.append(value)
    return None


async def _iterate_sse_messages(lines: AsyncIterator[str]) -> AsyncIterator[_SseEvent]:
    """Parse SSE events from an async line iterator."""
    state = _SseDecoderState()
    async for line in lines:
        event = _decode_sse_line(line, state)
        if event is not None:
            yield event
    event = _flush_sse_event(state)
    if event is not None:
        yield event


async def _iterate_anthropic_events(
    response: httpx.Response,
    signal: Any | None = None,
) -> AsyncIterator[dict[str, Any]]:
    """Yield parsed Anthropic stream events from an HTTP response."""
    saw_start = False
    saw_end = False
    async for sse in _iterate_sse_messages(response.aiter_lines()):
        if getattr(signal, "aborted", False):
            raise Error("Request was aborted")
        if sse.event == "error":
            raise Error(sse.data)
        if sse.event not in _ANTHROPIC_MESSAGE_EVENTS:
            continue
        try:
            event = parse_json_with_repair(sse.data)
            if event.get("type") == "message_start":
                saw_start = True
            elif event.get("type") == "message_stop":
                saw_end = True
            yield event
        except Exception as exc:
            msg = str(exc)
            raw = "\\n".join(sse.raw)
            raise Error(
                f"Could not parse Anthropic SSE event {sse.event}: {msg}; "
                f"data={sse.data}; raw={raw}"
            ) from exc
    if saw_start and not saw_end:
        raise Error("Anthropic stream ended before message_stop")


# ---------------------------------------------------------------------------
# Private helpers
# ---------------------------------------------------------------------------


def _get_cache_control(
    model: Model,
    cache_retention: CacheRetention | None = None,
) -> tuple[CacheRetention, dict[str, Any] | None]:
    retention = resolve_cache_retention(cache_retention)
    if retention == "none":
        return retention, None
    compat = _get_anthropic_compat(model)
    ttl = "1h" if retention == "long" and compat.get("supports_long_cache_retention", True) else None
    cache_control: dict[str, Any] = {"type": "ephemeral"}
    if ttl:
        cache_control["ttl"] = ttl
    return retention, cache_control


def _merge_headers(
    *header_sources: dict[str, str | None] | None,
) -> dict[str, str | None]:
    merged: dict[str, str | None] = {}
    for source in header_sources:
        if source:
            merged.update(source)
    return merged


def _is_oauth_token(api_key: str) -> bool:
    return "sk-ant-oat" in api_key


def _to_claude_code_name(name: str) -> str:
    return _CC_TOOL_LOOKUP.get(name.lower(), name)


def _from_claude_code_name(name: str, tools: list[Tool] | None = None) -> str:
    if tools:
        lower_name = name.lower()
        for tool in tools:
            if tool.name.lower() == lower_name:
                return tool.name
    return name


def _convert_content_blocks(
    content: list[TextContent | ImageContent],
) -> str | list[dict[str, Any]]:
    has_images = any(c.type == "image" for c in content)
    if not has_images:
        return sanitize_surrogates("\n".join(c.text for c in content if c.type == "text"))
    blocks: list[dict[str, Any]] = []
    for block in content:
        if block.type == "text":
            blocks.append({"type": "text", "text": sanitize_surrogates(block.text)})
        else:
            blocks.append({
                "type": "image",
                "source": {
                    "type": "base64",
                    "media_type": block.mime_type,
                    "data": block.data,
                },
            })
    if not any(b["type"] == "text" for b in blocks):
        blocks.insert(0, {"type": "text", "text": "(see attached image)"})
    return blocks


def _get_anthropic_compat(model: Model) -> dict[str, Any]:
    compat = model.compat
    if compat is None or not isinstance(compat, AnthropicMessagesCompat):
        return {
            "supports_eager_tool_input_streaming": True,
            "supports_long_cache_retention": True,
        }
    return {
        "supports_eager_tool_input_streaming": compat.supports_eager_tool_input_streaming if compat.supports_eager_tool_input_streaming is not None else True,
        "supports_long_cache_retention": compat.supports_long_cache_retention if compat.supports_long_cache_retention is not None else True,
    }


def _supports_adaptive_thinking(model_id: str) -> bool:
    return any(
        tag in model_id
        for tag in (
            "opus-4-6", "opus-4.6",
            "opus-4-7", "opus-4.7",
            "opus-4-8", "opus-4.8",
            "sonnet-4-6", "sonnet-4.6",
        )
    )


def _default_thinking_display(model_id: str) -> AnthropicThinkingDisplay:
    if "opus-4-8" in model_id or "opus-4.8" in model_id:
        return "omitted"
    return "summarized"


def _map_thinking_level_to_effort(
    model: Model,
    level: str | None,
) -> AnthropicEffort:
    if level and model.thinking_level_map:
        mapped = model.thinking_level_map.get(level)
        if mapped is not None:
            return mapped  # type: ignore[return-value]
    if level:
        return ANTHROPIC_THINKING_LEVEL_TO_EFFORT.get(level, "high")  # type: ignore[return-value]
    return "high"


def _should_use_fine_grained_tool_streaming_beta(
    model: Model, context: Context
) -> bool:
    return bool(context.tools) and not _get_anthropic_compat(model).get(
        "supports_eager_tool_input_streaming", True
    )


def _normalize_tool_call_id(tool_id: str) -> str:
    return re.sub(r"[^a-zA-Z0-9_-]", "_", tool_id)[:64]


def _map_stop_reason(reason: str) -> StopReason:
    mapped = _STOP_REASON_MAP.get(reason)
    if mapped is None:
        raise ValueError(f"Unhandled stop reason: {reason}")
    return mapped


def _convert_messages(
    messages: list[Message],
    model: Model,
    is_oauth_token: bool,
    cache_control: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    params: list[dict[str, Any]] = []
    transformed_messages = transform_messages(messages, model, _normalize_tool_call_id)

    i = 0
    while i < len(transformed_messages):
        msg = transformed_messages[i]

        if msg.role == "user":
            if isinstance(msg.content, str):
                if msg.content.strip():
                    params.append({
                        "role": "user",
                        "content": sanitize_surrogates(msg.content),
                    })
            else:
                blocks: list[dict[str, Any]] = []
                for item in msg.content:
                    if item.type == "text":
                        blocks.append({
                            "type": "text",
                            "text": sanitize_surrogates(item.text),
                        })
                    else:
                        blocks.append({
                            "type": "image",
                            "source": {
                                "type": "base64",
                                "media_type": item.mime_type,
                                "data": item.data,
                            },
                        })
                filtered = [b for b in blocks if b["type"] != "text" or b["text"].strip()]
                if not filtered:
                    i += 1
                    continue
                params.append({"role": "user", "content": filtered})

        elif msg.role == "assistant":
            blocks = []
            for block in msg.content:
                if block.type == "text":
                    if not block.text.strip():
                        continue
                    blocks.append({
                        "type": "text",
                        "text": sanitize_surrogates(block.text),
                    })
                elif block.type == "thinking":
                    if block.redacted:
                        blocks.append({
                            "type": "redacted_thinking",
                            "data": block.thinking_signature or "",
                        })
                        continue
                    if not block.thinking.strip():
                        continue
                    if not block.thinking_signature or not block.thinking_signature.strip():
                        blocks.append({
                            "type": "text",
                            "text": sanitize_surrogates(block.thinking),
                        })
                    else:
                        blocks.append({
                            "type": "thinking",
                            "thinking": sanitize_surrogates(block.thinking),
                            "signature": block.thinking_signature,
                        })
                elif block.type == "toolCall":
                    blocks.append({
                        "type": "tool_use",
                        "id": block.id,
                        "name": _to_claude_code_name(block.name) if is_oauth_token else block.name,
                        "input": block.arguments or {},
                    })
            if blocks:
                params.append({"role": "assistant", "content": blocks})

        elif msg.role == "toolResult":
            tool_results: list[dict[str, Any]] = []
            tool_results.append({
                "type": "tool_result",
                "tool_use_id": msg.tool_call_id,
                "content": _convert_content_blocks(msg.content),
                "is_error": msg.is_error,
            })
            j = i + 1
            while j < len(transformed_messages) and transformed_messages[j].role == "toolResult":
                next_msg = transformed_messages[j]
                tool_results.append({
                    "type": "tool_result",
                    "tool_use_id": next_msg.tool_call_id,
                    "content": _convert_content_blocks(next_msg.content),
                    "is_error": next_msg.is_error,
                })
                j += 1
            i = j - 1  # will be incremented at end of loop
            params.append({"role": "user", "content": tool_results})

        i += 1

    if cache_control and params:
        last = params[-1]
        if last["role"] == "user":
            content = last["content"]
            if isinstance(content, list) and content:
                last_block = content[-1]
                if last_block["type"] in ("text", "image", "tool_result"):
                    last_block["cache_control"] = cache_control
            elif isinstance(content, str):
                last["content"] = [
                    {"type": "text", "text": content, "cache_control": cache_control}
                ]

    return params


def _convert_tools(
    tools: list[Tool],
    is_oauth_token: bool,
    supports_eager_streaming: bool,
    cache_control: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not tools:
        return []
    result: list[dict[str, Any]] = []
    for idx, tool in enumerate(tools):
        schema = tool.parameters
        entry: dict[str, Any] = {
            "name": _to_claude_code_name(tool.name) if is_oauth_token else tool.name,
            "description": tool.description,
            "input_schema": {
                "type": "object",
                "properties": schema.get("properties", {}),
                "required": schema.get("required", []),
            },
        }
        if supports_eager_streaming:
            entry["eager_input_streaming"] = True
        if cache_control and idx == len(tools) - 1:
            entry["cache_control"] = cache_control
        result.append(entry)
    return result


