class Error(Exception):
    """Raised when the Anthropic API call fails."""


class AnthropicClient:
    """HTTP client for the Anthropic Messages API (replaces @anthropic-ai/sdk)."""

    def __init__(
        self,
        *,
        base_url: str,
        api_key: str | None = None,
        auth_token: str | None = None,
        default_headers: dict[str, str | None] | None = None,
    ) -> None:
        self._base_url = base_url.rstrip("/")
        self._api_key = api_key
        self._auth_token = auth_token
        self._default_headers: dict[str, str | None] = default_headers or {}

    async def create_message(
        self,
        params: dict[str, Any],
        *,
        signal: Any | None = None,
        timeout: int | None = None,
        max_retries: int | None = None,
    ) -> httpx.Response:
        """POST to /v1/messages and return the raw httpx.Response."""
        headers: dict[str, str] = {}
        for k, v in self._default_headers.items():
            if v is not None:
                headers[k] = v
        if self._auth_token:
            headers["Authorization"] = f"Bearer {self._auth_token}"
        elif self._api_key:
            headers["x-api-key"] = self._api_key
        headers["anthropic-version"] = ANTHROPIC_VERSION
        headers["content-type"] = "application/json"

        url = f"{self._base_url}/v1/messages"
        timeout_s = (timeout / 1000) if timeout else 300.0

        async with httpx.AsyncClient(timeout=timeout_s) as client:
            response = await client.post(url, json=params, headers=headers)
            return response


def _create_client(
    model: Model,
    api_key: str,
    interleaved_thinking: bool,
    use_fine_grained_beta: bool,
    options_headers: dict[str, str] | None = None,
    dynamic_headers: dict[str, str] | None = None,
) -> tuple[AnthropicClient, bool]:
    needs_interleaved_beta = interleaved_thinking and not _supports_adaptive_thinking(model.id)
    beta_features: list[str] = []
    if use_fine_grained_beta:
        beta_features.append(FINE_GRAINED_TOOL_STREAMING_BETA)
    if needs_interleaved_beta:
        beta_features.append(INTERLEAVED_THINKING_BETA)

    if model.provider == "github-copilot":
        client = AnthropicClient(
            base_url=model.base_url,
            auth_token=api_key,
            default_headers=_merge_headers(
                {
                    "accept": "application/json",
                    "anthropic-dangerous-direct-browser-access": "true",
                    **({"anthropic-beta": ",".join(beta_features)} if beta_features else {}),
                },
                model.headers,
                dynamic_headers,
                options_headers,
            ),
        )
        return client, False

    if _is_oauth_token(api_key):
        client = AnthropicClient(
            base_url=model.base_url,
            auth_token=api_key,
            default_headers=_merge_headers(
                {
                    "accept": "application/json",
                    "anthropic-dangerous-direct-browser-access": "true",
                    "anthropic-beta": ["claude-code-20250219", "oauth-2025-04-20", *beta_features].join(",") if beta_features else "claude-code-20250219,oauth-2025-04-20",
                    "user-agent": f"claude-cli/{CLAUDE_CODE_VERSION}",
                    "x-app": "cli",
                },
                model.headers,
                options_headers,
            ),
        )
        return client, True

    client = AnthropicClient(
        base_url=model.base_url,
        api_key=api_key,
        default_headers=_merge_headers(
            {
                "accept": "application/json",
                "anthropic-dangerous-direct-browser-access": "true",
                **({"anthropic-beta": ",".join(beta_features)} if beta_features else {}),
            },
            model.headers,
            options_headers,
        ),
    )
    return client, False


def _build_params(
    model: Model,
    context: Context,
    is_oauth: bool,
    options: AnthropicOptions | None = None,
) -> dict[str, Any]:
    _retention, cache_control = _get_cache_control(
        model, options.cache_retention if options else None
    )
    params: dict[str, Any] = {
        "model": model.id,
        "messages": _convert_messages(
            context.messages, model, is_oauth, cache_control
        ),
        "max_tokens": (options.max_tokens if options and options.max_tokens is not None else (model.max_tokens // 3)),
        "stream": True,
    }

    if is_oauth:
        system: list[dict[str, Any]] = [{
            "type": "text",
            "text": "You are Claude Code, Anthropic's official CLI for Claude.",
            **(({"cache_control": cache_control}) if cache_control else {}),
        }]
        if context.system_prompt:
            system.append({
                "type": "text",
                "text": sanitize_surrogates(context.system_prompt),
                **(({"cache_control": cache_control}) if cache_control else {}),
            })
        params["system"] = system
    elif context.system_prompt:
        params["system"] = [{
            "type": "text",
            "text": sanitize_surrogates(context.system_prompt),
            **(({"cache_control": cache_control}) if cache_control else {}),
        }]

    if options and options.temperature is not None and not options.thinking_enabled:
        params["temperature"] = options.temperature

    if context.tools:
        compat = _get_anthropic_compat(model)
        params["tools"] = _convert_tools(
            context.tools,
            is_oauth,
            compat.get("supports_eager_tool_input_streaming", True),
            cache_control,
        )

    if model.reasoning:
        if options and options.thinking_enabled:
            display: AnthropicThinkingDisplay = (
                options.thinking_display
                if options.thinking_display is not None
                else _default_thinking_display(model.id)
            )
            if _supports_adaptive_thinking(model.id):
                params["thinking"] = {"type": "adaptive", "display"}
                if options.effort:
                    params["output_config"] = {"effort": options.effort}
            else:
                params["thinking"] = {
                    "type": "enabled",
                    "budget_tokens": options.thinking_budget_tokens or 1024,
                    "display": display,
                }
        elif options and options.thinking_enabled is False:
            params["thinking"] = {"type": "disabled"}

    if options and options.metadata:
        user_id = options.metadata.get("user_id")
        if isinstance(user_id, str):
            params["metadata"] = {"user_id": user_id}

    if options and options.tool_choice:
        if isinstance(options.tool_choice, str):
            params["tool_choice"] = {"type": options.tool_choice}
        else:
            params["tool_choice"] = options.tool_choice

    return params


