def stream_anthropic(
    model: Model,
    context: Context,
    options: AnthropicOptions | None = None,
) -> AssistantMessageEventStream:
    stream = create_assistant_message_event_stream()

    async def _run() -> None:
        output = AssistantMessage(
            role="assistant",
            content=[],
            api=model.api,
            provider=model.provider,
            model=model.id,
            usage=Usage(
                input=0,
                output=0,
                cache_read=0,
                cache_write=0,
                total_tokens=0,
                cost={"input": 0.0, "output": 0.0, "cache_read": 0.0, "cache_write": 0.0, "total": 0.0},
            ),
            stop_reason="stop",
            timestamp=int(time.time() * 1000),
        )

        try:
            client: Any
            is_oauth: bool

            if options and options.client:
                client = options.client
                is_oauth = False
            else:
                api_key = (options.api_key if options else None) or get_env_api_key(model.provider) or ""

                copilot_dynamic_headers: dict[str, str] | None = None
                if model.provider == "github-copilot":
                    has_images = has_copilot_vision_input(context.messages)
                    copilot_dynamic_headers = build_copilot_dynamic_headers(context.messages, has_images)

                client, is_oauth = _create_client(
                    model,
                    api_key,
                    (options.interleaved_thinking if options and options.interleaved_thinking is not None else True),
                    _should_use_fine_grained_tool_streaming_beta(model, context),
                    options.headers if options else None,
                    copilot_dynamic_headers,
                )

            params = _build_params(model, context, is_oauth, options)

            if options and options.on_payload is not None:
                next_params = options.on_payload(params, model)
                if inspect.isawaitable(next_params):
                    next_params = await next_params
                if next_params is not None:
                    params = next_params

            signal = options.signal if options else None
            timeout_ms = options.timeout_ms if options else None
            max_retries = options.max_retries if options else None

            response = await client.create_message(
                params,
                signal=signal,
                timeout=timeout_ms,
                max_retries=max_retries,
            )

            if options and options.on_response is not None:
                resp_info = {"status": response.status_code, "headers": headers_to_record(response.headers)}
                result = options.on_response(resp_info, model)
                if inspect.isawaitable(result):
                    await result

            stream.push(StartEvent(partial=output))

            # Track blocks: index in output.content → block dict
            _block_map: dict[int, dict[str, Any]] = {}

            async for event in _iterate_anthropic_events(response, signal):
                event_type = event.get("type")

                if event_type == "message_start":
                    msg = event.get("message", {})
                    output.response_id = msg.get("id")
                    usage = msg.get("usage", {})
                    output.usage.input = usage.get("input_tokens") or 0
                    output.usage.output = usage.get("output_tokens") or 0
                    output.usage.cache_read = usage.get("cache_read_input_tokens") or 0
                    output.usage.cache_write = usage.get("cache_creation_input_tokens") or 0
                    output.usage.total_tokens = (
                        output.usage.input + output.usage.output
                        + output.usage.cache_read + output.usage.cache_write
                    )
                    output.usage.cost = calculate_cost(model, output.usage)

                elif event_type == "content_block_start":
                    cb = event.get("content_block", {})
                    cb_type = cb.get("type")
                    idx = event.get("index", 0)

                    if cb_type == "text":
                        output.content.append(TextContent(text=""))
                        _block_map[idx] = {"type": "text", "content_index": len(output.content) - 1}
                        stream.push(TextStartEvent(content_index=len(output.content) - 1, partial=output))
                    elif cb_type == "thinking":
                        output.content.append(ThinkingContent(thinking="", thinking_signature=""))
                        _block_map[idx] = {"type": "thinking", "content_index": len(output.content) - 1}
                        stream.push(ThinkingStartEvent(content_index=len(output.content) - 1, partial=output))
                    elif cb_type == "redacted_thinking":
                        output.content.append(ThinkingContent(
                            thinking="[Reasoning redacted]",
                            thinking_signature=cb.get("data", ""),
                            redacted=True,
                        ))
                        _block_map[idx] = {"type": "thinking", "content_index": len(output.content) - 1}
                        stream.push(ThinkingStartEvent(content_index=len(output.content) - 1, partial=output))
                    elif cb_type == "tool_use":
                        name = cb.get("name", "")
                        if is_oauth:
                            name = _from_claude_code_name(name, context.tools)
                        output.content.append(ToolCall(
                            id=cb.get("id", ""),
                            name=name,
                            arguments=cb.get("input") or {},
                        ))
                        _block_map[idx] = {
                            "type": "toolCall",
                            "content_index": len(output.content) - 1,
                            "partial_json": "",
                        }
                        stream.push(ToolCallStartEvent(content_index=len(output.content) - 1, partial=output))

                elif event_type == "content_block_delta":
                    delta = event.get("delta", {})
                    delta_type = delta.get("type")
                    idx = event.get("index", 0)
                    info = _block_map.get(idx)
                    if not info:
                        continue
                    ci = info["content_index"]

                    if delta_type == "text_delta":
                        block = output.content[ci]
                        if isinstance(block, TextContent):
                            block.text += delta.get("text", "")
                            stream.push(TextDeltaEvent(content_index=ci, delta=delta.get("text", ""), partial=output))
                    elif delta_type == "thinking_delta":
                        block = output.content[ci]
                        if isinstance(block, ThinkingContent):
                            block.thinking += delta.get("thinking", "")
                            stream.push(ThinkingDeltaEvent(content_index=ci, delta=delta.get("thinking", ""), partial=output))
                    elif delta_type == "input_json_delta":
                        if info["type"] == "toolCall":
                            info["partial_json"] += delta.get("partial_json", "")
                            block = output.content[ci]
                            if isinstance(block, ToolCall):
                                block.arguments = parse_streaming_json(info["partial_json"])
                            stream.push(ToolCallDeltaEvent(content_index=ci, delta=delta.get("partial_json", ""), partial=output))
                    elif delta_type == "signature_delta":
                        block = output.content[ci]
                        if isinstance(block, ThinkingContent):
                            block.thinking_signature = (block.thinking_signature or "") + delta.get("signature", "")

                elif event_type == "content_block_stop":
                    idx = event.get("index", 0)
                    info = _block_map.get(idx)
                    if not info:
                        continue
                    ci = info["content_index"]

                    if info["type"] == "text":
                        block = output.content[ci]
                        if isinstance(block, TextContent):
                            stream.push(TextEndEvent(content_index=ci, content=block.text, partial=output))
                    elif info["type"] == "thinking":
                        block = output.content[ci]
                        if isinstance(block, ThinkingContent):
                            stream.push(ThinkingEndEvent(content_index=ci, content=block.thinking, partial=output))
                    elif info["type"] == "toolCall":
                        block = output.content[ci]
                        if isinstance(block, ToolCall):
                            block.arguments = parse_streaming_json(info["partial_json"])
                        stream.push(ToolCallEndEvent(content_index=ci, tool_call=block, partial=output))  # type: ignore[arg-type]

                elif event_type == "message_delta":
                    delta = event.get("delta", {})
                    if delta.get("stop_reason"):
                        output.stop_reason = _map_stop_reason(delta["stop_reason"])
                    usage = event.get("usage", {})
                    if usage.get("input_tokens") is not None:
                        output.usage.input = usage["input_tokens"]
                    if usage.get("output_tokens") is not None:
                        output.usage.output = usage["output_tokens"]
                    if usage.get("cache_read_input_tokens") is not None:
                        output.usage.cache_read = usage["cache_read_input_tokens"]
                    if usage.get("cache_creation_input_tokens") is not None:
                        output.usage.cache_write = usage["cache_creation_input_tokens"]
                    output.usage.total_tokens = (
                        output.usage.input + output.usage.output
                        + output.usage.cache_read + output.usage.cache_write
                    )
                    output.usage.cost = calculate_cost(model, output.usage)

            if getattr(signal, "aborted", False):
                raise Error("Request was aborted")

            if output.stop_reason == "aborted" or output.stop_reason == "error":
                raise Error("An unknown error occurred")

            stream.push(DoneEvent(reason=output.stop_reason, message=output))  # type: ignore[arg-type]
            stream.end()

        except Exception as exc:
            output.stop_reason = "aborted" if getattr(signal, "aborted", False) else "error"
            output.error_message = str(exc)
            stream.push(ErrorEvent(reason=output.stop_reason, error=output))  # type: ignore[arg-type])
            stream.end()

    asyncio.ensure_future(_run())
    return stream


def stream_simple_anthropic(
